[CmdletBinding()]param()
Set-StrictMode -Version 3.0;$ErrorActionPreference='Stop';$patchRoot=Split-Path -Parent $PSScriptRoot;. (Join-Path $patchRoot 'RootTopology.Transactions.ps1')
function Assert-Topology([bool]$Condition,[string]$Message){if(-not$Condition){throw $Message}}
function New-V3TopologyFixture([string]$Root){
    New-Item -ItemType Directory -Path (Join-Path $Root 'launcher'),(Join-Path $Root 'UserDesktop') -Force|Out-Null
    [IO.File]::WriteAllText((Join-Path $Root 'Billfish.exe'),'vendor-core-v3');[IO.File]::WriteAllText((Join-Path $Root 'launcher\Billfish.exe'),'legacy-wrapper-v3');[IO.File]::WriteAllText((Join-Path $Root 'root-wrapper-staging.exe'),'root-wrapper-v4');[IO.File]::WriteAllText((Join-Path $Root 'start-billfish.ps1'),'# fixture')
    $context=Get-BillfishEntryPointContext $Root;$origin=[pscustomobject]@{TargetPath='C:\Origin\Billfish.exe';Arguments='--origin';WorkingDirectory='C:\Origin';IconLocation='C:\Origin\Billfish.exe,0';Description='Origin';WindowStyle=1};Write-BillfishShortcut (Join-Path $Root 'UserDesktop\Billfish.lnk') $origin $true;Set-BillfishRunValue $context 'origin-run' $true
    $v3Pointer=Join-Path $Root 'latest-user-shortcut-backup.txt';$v3Backup=Join-Path $Root 'v3-backup';[void](Install-BillfishEntryPoints -BillfishRoot $Root -BackupDir $v3Backup -FixtureRoot $Root -StatePointerPath $v3Pointer)
    [pscustomobject]@{Root=$Root;Context=$context;V3Pointer=$v3Pointer;V3Backup=$v3Backup;V4Pointer=Join-Path $Root 'latest-root-topology-backup.txt';V4Backup=Join-Path $Root 'v4-backup';Staging=Join-Path $Root 'root-wrapper-staging.exe'}
}
function Assert-V3Installed([object]$Case){Assert-Topology (([IO.File]::ReadAllText((Join-Path $Case.Root 'Billfish.exe')))-eq'vendor-core-v3') 'Root vendor was not restored.';Assert-Topology (([IO.File]::ReadAllText((Join-Path $Case.Root 'launcher\Billfish.exe')))-eq'legacy-wrapper-v3') 'Legacy wrapper was not restored.';Assert-Topology (-not(Test-Path (Join-Path $Case.Root 'Billfish.core.exe'))) 'Core remained after v3 recovery.';$link=Read-BillfishShortcut (Join-Path $Case.Root 'UserDesktop\Billfish.lnk') $true;Assert-Topology ($link.TargetPath-eq(Join-Path $Case.Root 'launcher\Billfish.exe')) 'v3 shortcut target was not restored.'}
function Assert-V4Installed([object]$Case){Assert-Topology (([IO.File]::ReadAllText((Join-Path $Case.Root 'Billfish.exe')))-eq'root-wrapper-v4') 'Root wrapper missing.';Assert-Topology (([IO.File]::ReadAllText((Join-Path $Case.Root 'Billfish.core.exe')))-eq'vendor-core-v3') 'Core missing.';Assert-Topology (-not(Test-Path (Join-Path $Case.Root 'launcher\Billfish.exe'))) 'Legacy wrapper remained.';$link=Read-BillfishShortcut (Join-Path $Case.Root 'UserDesktop\Billfish.lnk') $true;Assert-Topology ($link.TargetPath-eq(Join-Path $Case.Root 'Billfish.exe')-and$link.IconLocation-eq((Join-Path $Case.Root 'Billfish.core.exe')+',0')) 'v4 shortcut topology is wrong.'}

$fixture=Join-Path ([IO.Path]::GetTempPath()) ('billfish-root-topology-'+[guid]::NewGuid().ToString('N'))
try{
    $case=New-V3TopologyFixture (Join-Path $fixture 'success');$installed=Install-BillfishRootTopology -BillfishRoot $case.Root -WrapperStagingPath $case.Staging -BackupDir $case.V4Backup -V3StatePointerPath $case.V3Pointer -V4StatePointerPath $case.V4Pointer -FixtureRoot $case.Root;Assert-Topology ($installed.Outcome-eq'Installed') 'v4 install failed.';Assert-V4Installed $case;$topologyStatus=& (Join-Path $patchRoot 'status-unified-billfish.ps1') -CheckInstallationHistory -BillfishRoot $case.Root -FixtureRoot $case.Root -TestSkipWrapperMetadataCheck -TestSkipPersistentPatchHealth;Assert-Topology $topologyStatus.Healthy 'v4 unified status is not healthy.'
    $deleteChildDenied=New-V3TopologyFixture (Join-Path $fixture 'delete-child-denied');$originalRootAcl=Get-Acl -LiteralPath $deleteChildDenied.Root;try{$denyDeleteChild=New-Object System.Security.AccessControl.FileSystemAccessRule([System.Security.Principal.WindowsIdentity]::GetCurrent().User,[System.Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles,[System.Security.AccessControl.AccessControlType]::Deny);$restrictedRootAcl=Get-Acl -LiteralPath $deleteChildDenied.Root;[void]$restrictedRootAcl.AddAccessRule($denyDeleteChild);Set-Acl -LiteralPath $deleteChildDenied.Root -AclObject $restrictedRootAcl;$legacyOpenDenied=$false;try{$legacyHandle=[Billfish.Launcher.HandleNativeMethods]::OpenDirectory($deleteChildDenied.Root);try{}finally{$legacyHandle.Dispose()}}catch [System.ComponentModel.Win32Exception]{$legacyOpenDenied=$_.Exception.NativeErrorCode-eq5};Assert-Topology $legacyOpenDenied 'Ordinary directory opening did not reject FILE_DELETE_CHILD.';$topologyHandle=[Billfish.Launcher.HandleNativeMethods]::OpenDirectoryForTopologyPlacement($deleteChildDenied.Root);try{Assert-Topology ($null-ne$topologyHandle) 'Topology directory opening did not use the lower-permission access mask.'}finally{$topologyHandle.Dispose()};$restrictedInstall=Install-BillfishRootTopology -BillfishRoot $deleteChildDenied.Root -WrapperStagingPath $deleteChildDenied.Staging -BackupDir $deleteChildDenied.V4Backup -V3StatePointerPath $deleteChildDenied.V3Pointer -V4StatePointerPath $deleteChildDenied.V4Pointer -FixtureRoot $deleteChildDenied.Root;Assert-Topology ($restrictedInstall.Outcome-eq'Installed') 'v4 install failed when the root denied FILE_DELETE_CHILD.';Assert-V4Installed $deleteChildDenied}finally{Set-Acl -LiteralPath $deleteChildDenied.Root -AclObject $originalRootAcl}
    [IO.File]::WriteAllText($case.V4Pointer,(Join-Path $case.Root 'missing-backup')+[Environment]::NewLine);$statusOutput=& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $patchRoot 'status-unified-billfish.ps1') -CheckInstallationHistory -BillfishRoot $case.Root -FixtureRoot $case.Root -TestSkipWrapperMetadataCheck -TestSkipPersistentPatchHealth -AsJson 2>&1;$statusExit=$LASTEXITCODE;$driftStatus=($statusOutput-join[Environment]::NewLine)|ConvertFrom-Json;Assert-Topology ($statusExit-eq2-and-not$driftStatus.Healthy) 'Status accepted a drifted v4 pointer.';[IO.File]::WriteAllText($case.V4Pointer,$case.V4Backup+[Environment]::NewLine)
    $corePath=Join-Path $case.Root 'Billfish.core.exe';$coreBytes=[IO.File]::ReadAllBytes($corePath);try{[IO.File]::AppendAllText($corePath,'drift');$statusOutput=& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $patchRoot 'status-unified-billfish.ps1') -CheckInstallationHistory -BillfishRoot $case.Root -FixtureRoot $case.Root -TestSkipWrapperMetadataCheck -TestSkipPersistentPatchHealth -AsJson 2>&1;$statusExit=$LASTEXITCODE;$driftStatus=($statusOutput-join[Environment]::NewLine)|ConvertFrom-Json;Assert-Topology ($statusExit-eq2-and-not$driftStatus.Healthy) 'Status accepted a drifted core fingerprint.'}finally{[IO.File]::WriteAllBytes($corePath,$coreBytes)}
    $again=Install-BillfishRootTopology -BillfishRoot $case.Root -WrapperStagingPath $case.Staging -BackupDir (Join-Path $case.Root 'unused') -V3StatePointerPath $case.V3Pointer -V4StatePointerPath $case.V4Pointer -FixtureRoot $case.Root;Assert-Topology ($again.Outcome-eq'AlreadyInstalled') 'v4 install is not idempotent.'
    $restored=Restore-BillfishRootTopology -BillfishRoot $case.Root -BackupDir $case.V4Backup -V4StatePointerPath $case.V4Pointer -FixtureRoot $case.Root;Assert-Topology ($restored.Outcome-eq'Restored') 'v4 restore failed.';Assert-V3Installed $case;Assert-Topology ((Get-Content $case.V3Pointer -TotalCount 1).Trim()-eq$case.V3Backup) 'First v3 origin pointer contract changed.'

    foreach($phase in @('Core','RootWrapper','Entries','Run','LegacyWrapper','Pointer')){$failureCase=New-V3TopologyFixture (Join-Path $fixture ('fail-'+$phase));$failed=$false;try{Install-BillfishRootTopology -BillfishRoot $failureCase.Root -WrapperStagingPath $failureCase.Staging -BackupDir $failureCase.V4Backup -V3StatePointerPath $failureCase.V3Pointer -V4StatePointerPath $failureCase.V4Pointer -FixtureRoot $failureCase.Root -FailPhase $phase|Out-Null}catch{$failed=$true};Assert-Topology $failed "Install phase $phase did not fail.";Assert-V3Installed $failureCase;Assert-Topology (-not(Test-Path ($failureCase.V4Pointer+'.pending.json'))) "Install phase $phase retained pending state."}

    foreach($phase in @('Core','RootWrapper','Entries','Run','LegacyWrapper')){$pendingCase=New-V3TopologyFixture (Join-Path $fixture ('pending-'+$phase));$pending=Install-BillfishRootTopology -BillfishRoot $pendingCase.Root -WrapperStagingPath $pendingCase.Staging -BackupDir $pendingCase.V4Backup -V3StatePointerPath $pendingCase.V3Pointer -V4StatePointerPath $pendingCase.V4Pointer -FixtureRoot $pendingCase.Root -LeavePendingAfterPhase $phase;Assert-Topology ($pending.Outcome-eq'PendingSimulated') "Pending phase $phase was not simulated.";$recovered=Install-BillfishRootTopology -BillfishRoot $pendingCase.Root -WrapperStagingPath $pendingCase.Staging -BackupDir (Join-Path $pendingCase.Root 'unused') -V3StatePointerPath $pendingCase.V3Pointer -V4StatePointerPath $pendingCase.V4Pointer -FixtureRoot $pendingCase.Root -RecoverOnly;Assert-Topology ($recovered.Outcome-eq'Recovered') "Pending phase $phase was not recovered.";Assert-V3Installed $pendingCase;Assert-Topology (-not(Test-Path $pendingCase.V4Pointer)) "Pending phase $phase left a v4 pointer.";$repeated=Install-BillfishRootTopology -BillfishRoot $pendingCase.Root -WrapperStagingPath $pendingCase.Staging -BackupDir (Join-Path $pendingCase.Root 'unused-2') -V3StatePointerPath $pendingCase.V3Pointer -V4StatePointerPath $pendingCase.V4Pointer -FixtureRoot $pendingCase.Root -RecoverOnly;Assert-Topology ($repeated.Outcome-eq'NoPendingTransaction') "Pending phase $phase recovery was not repeatable."}

    $pointerPending=New-V3TopologyFixture (Join-Path $fixture 'pending-Pointer');$pending=Install-BillfishRootTopology -BillfishRoot $pointerPending.Root -WrapperStagingPath $pointerPending.Staging -BackupDir $pointerPending.V4Backup -V3StatePointerPath $pointerPending.V3Pointer -V4StatePointerPath $pointerPending.V4Pointer -FixtureRoot $pointerPending.Root -LeavePendingAfterPhase Pointer;Assert-Topology ($pending.Outcome-eq'PendingSimulated') 'Pointer pending phase was not simulated.';$recovered=Install-BillfishRootTopology -BillfishRoot $pointerPending.Root -WrapperStagingPath $pointerPending.Staging -BackupDir (Join-Path $pointerPending.Root 'unused') -V3StatePointerPath $pointerPending.V3Pointer -V4StatePointerPath $pointerPending.V4Pointer -FixtureRoot $pointerPending.Root -RecoverOnly;Assert-Topology ($recovered.Outcome-eq'Recovered') 'Pointer pending commit was not recovered.';Assert-V4Installed $pointerPending;Assert-Topology ((Get-Content $pointerPending.V4Pointer -TotalCount 1).Trim()-eq$pointerPending.V4Backup) 'Pointer pending commit lost its active pointer.';$repeated=Install-BillfishRootTopology -BillfishRoot $pointerPending.Root -WrapperStagingPath $pointerPending.Staging -BackupDir (Join-Path $pointerPending.Root 'unused-2') -V3StatePointerPath $pointerPending.V3Pointer -V4StatePointerPath $pointerPending.V4Pointer -FixtureRoot $pointerPending.Root -RecoverOnly;Assert-Topology ($repeated.Outcome-eq'NoPendingTransaction') 'Pointer commit recovery was not repeatable.'
    $pointerDrift=New-V3TopologyFixture (Join-Path $fixture 'pending-Pointer-drift');[void](Install-BillfishRootTopology -BillfishRoot $pointerDrift.Root -WrapperStagingPath $pointerDrift.Staging -BackupDir $pointerDrift.V4Backup -V3StatePointerPath $pointerDrift.V3Pointer -V4StatePointerPath $pointerDrift.V4Pointer -FixtureRoot $pointerDrift.Root -LeavePendingAfterPhase Pointer);[IO.File]::AppendAllText((Join-Path $pointerDrift.Root 'Billfish.core.exe'),'drift');$recovered=Install-BillfishRootTopology -BillfishRoot $pointerDrift.Root -WrapperStagingPath $pointerDrift.Staging -BackupDir (Join-Path $pointerDrift.Root 'unused') -V3StatePointerPath $pointerDrift.V3Pointer -V4StatePointerPath $pointerDrift.V4Pointer -FixtureRoot $pointerDrift.Root -RecoverOnly;Assert-Topology ($recovered.Outcome-eq'Recovered') 'Drifted pointer phase was not recovered.';Assert-V3Installed $pointerDrift;Assert-Topology (-not(Test-Path $pointerDrift.V4Pointer)) 'Drifted pointer recovery left a pointer to RolledBack state.'

    $restoreFailure=New-V3TopologyFixture (Join-Path $fixture 'restore-failure');[void](Install-BillfishRootTopology -BillfishRoot $restoreFailure.Root -WrapperStagingPath $restoreFailure.Staging -BackupDir $restoreFailure.V4Backup -V3StatePointerPath $restoreFailure.V3Pointer -V4StatePointerPath $restoreFailure.V4Pointer -FixtureRoot $restoreFailure.Root)
    foreach($phase in @('RootVendor','LegacyWrapper','Core','Entries','Run','Pointer')){$failed=$false;try{Restore-BillfishRootTopology -BillfishRoot $restoreFailure.Root -BackupDir $restoreFailure.V4Backup -V4StatePointerPath $restoreFailure.V4Pointer -FixtureRoot $restoreFailure.Root -FailPhase $phase|Out-Null}catch{$failed=$true};Assert-Topology $failed "Restore phase $phase did not fail.";Assert-V4Installed $restoreFailure}

    foreach($phase in @('RootVendor','Core','Entries','Run')){$pending=Restore-BillfishRootTopology -BillfishRoot $restoreFailure.Root -BackupDir $restoreFailure.V4Backup -V4StatePointerPath $restoreFailure.V4Pointer -FixtureRoot $restoreFailure.Root -LeavePendingAfterPhase $phase;Assert-Topology ($pending.Outcome-eq'PendingSimulated') "Restore pending phase $phase was not simulated.";$recovered=Install-BillfishRootTopology -BillfishRoot $restoreFailure.Root -WrapperStagingPath $restoreFailure.Staging -BackupDir (Join-Path $restoreFailure.Root 'unused') -V3StatePointerPath $restoreFailure.V3Pointer -V4StatePointerPath $restoreFailure.V4Pointer -FixtureRoot $restoreFailure.Root -RecoverOnly;Assert-Topology ($recovered.Outcome-eq'Recovered') "Restore pending phase $phase was not recovered.";Assert-V4Installed $restoreFailure}

    $publicRestore=New-V3TopologyFixture (Join-Path $fixture 'public-restore-pending');[void](Install-BillfishRootTopology -BillfishRoot $publicRestore.Root -WrapperStagingPath $publicRestore.Staging -BackupDir $publicRestore.V4Backup -V3StatePointerPath $publicRestore.V3Pointer -V4StatePointerPath $publicRestore.V4Pointer -FixtureRoot $publicRestore.Root);[void](Restore-BillfishRootTopology -BillfishRoot $publicRestore.Root -BackupDir $publicRestore.V4Backup -V4StatePointerPath $publicRestore.V4Pointer -FixtureRoot $publicRestore.Root -LeavePendingAfterPhase Pointer);$publicResult=& (Join-Path $patchRoot 'restore-root-launcher.ps1') -BillfishRoot $publicRestore.Root -FixtureRoot $publicRestore.Root;Assert-Topology ($publicResult.Outcome-eq'Restored') 'Public restore did not recover a pointer-phase interruption.';Assert-V3Installed $publicRestore

    $activeManifest=Read-BillfishTopologyManifest $restoreFailure.V4Backup;$entryBackup=@($activeManifest.v3Installed.shortcuts|Where-Object{[bool]$_.existed})[0].backup
    foreach($leaf in @('root-vendor.exe','legacy-wrapper.exe','root-wrapper.exe',[string]$entryBackup)){$tamper=Join-Path $restoreFailure.V4Backup $leaf;$original=[IO.File]::ReadAllBytes($tamper);try{[IO.File]::AppendAllText($tamper,'tamper');$tampered=$false;try{Restore-BillfishRootTopology -BillfishRoot $restoreFailure.Root -BackupDir $restoreFailure.V4Backup -V4StatePointerPath $restoreFailure.V4Pointer -FixtureRoot $restoreFailure.Root|Out-Null}catch{$tampered=$true};Assert-Topology $tampered "Tampered topology backup was accepted: $leaf"}finally{[IO.File]::WriteAllBytes($tamper,$original)}}
    $runningCase=New-V3TopologyFixture (Join-Path $fixture 'running');$blocked=$false;try{Install-BillfishRootTopology -BillfishRoot $runningCase.Root -WrapperStagingPath $runningCase.Staging -BackupDir $runningCase.V4Backup -V3StatePointerPath $runningCase.V3Pointer -V4StatePointerPath $runningCase.V4Pointer -FixtureRoot $runningCase.Root -TestProcessPaths (Join-Path $runningCase.Root 'Billfish.core.exe')|Out-Null}catch{$blocked=$true};Assert-Topology ($blocked-and-not(Test-Path $runningCase.V4Backup)) 'Running core preflight wrote transaction state.'
    $pluginCase=New-V3TopologyFixture (Join-Path $fixture 'plugin-running');$blocked=$false;try{Install-BillfishRootTopology -BillfishRoot $pluginCase.Root -WrapperStagingPath $pluginCase.Staging -BackupDir $pluginCase.V4Backup -V3StatePointerPath $pluginCase.V3Pointer -V4StatePointerPath $pluginCase.V4Pointer -FixtureRoot $pluginCase.Root -TestProcessPaths (Join-Path $pluginCase.Root 'PluginWorker64.exe')|Out-Null}catch{$blocked=$true};Assert-Topology ($blocked-and-not(Test-Path $pluginCase.V4Backup)) 'Running PluginWorker preflight wrote transaction state.'
    $lockedCase=New-V3TopologyFixture (Join-Path $fixture 'locked');$lockedStream=[IO.File]::Open((Join-Path $lockedCase.Root 'Billfish.exe'),[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$blocked=$false;try{Install-BillfishRootTopology -BillfishRoot $lockedCase.Root -WrapperStagingPath $lockedCase.Staging -BackupDir $lockedCase.V4Backup -V3StatePointerPath $lockedCase.V3Pointer -V4StatePointerPath $lockedCase.V4Pointer -FixtureRoot $lockedCase.Root|Out-Null}catch{$blocked=$true};Assert-Topology ($blocked-and-not(Test-Path $lockedCase.V4Backup)) 'Locked-file preflight wrote transaction state.'}finally{$lockedStream.Dispose()}
    [pscustomobject]@{Outcome='Passed';V3ToV4=$true;RootDeleteChildDenied=$true;PhaseRecovery=$true;PendingRecovery=$true;Idempotent=$true;Restore=$true;RestoreFailure=$true;TamperRejected=$true;RunningPreflight=$true;LockPreflight=$true}
}finally{if(Test-Path $fixture){Remove-Item $fixture -Recurse -Force}}
